// ─────────────────────────────────────────────────────────────────────────
//  01 · switch expressions and patterns★★☆
//  concepts: switch expressions · yield · instanceof patterns
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    enum Tier { STANDARD, EXPRESS, PICKUP }

    /** Shipping fee in cents for a tier and order total. */
    static long shippingCents(Tier tier, long orderCents) {
        return switch (tier) {
            case STANDARD -> orderCents >= 5000 ? 0 : 499;
            case EXPRESS -> {
                long fee = 1299;
                yield orderCents >= 10000 ? fee / 2 : fee;
            }
            case PICKUP -> 0;
        };
    }

    /** A short human description of a value. */
    static String describe(Object value) {
        if (value == null) return "null";
        if (value instanceof Integer i) return "int " + i;
        if (value instanceof String s) return s.isBlank() ? "blank string" : "string of length " + s.length();
        if (value instanceof List<?> l) return "list of " + l.size() + " items";
        return "other " + value.getClass().getSimpleName();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("standard shipping and its free threshold", () -> eq(List.of(shippingCents(Tier.STANDARD, 4999), shippingCents(Tier.STANDARD, 5000)), List.of(499L, 0L)));
        test("express is halved from 10000 cents", () -> eq(List.of(shippingCents(Tier.EXPRESS, 9999), shippingCents(Tier.EXPRESS, 12000)), List.of(1299L, 649L)));
        test("pickup is free (boundary)", () -> eq(shippingCents(Tier.PICKUP, 0), 0L));
        test("describe numbers, strings and lists", () -> eq(List.of(describe(42), describe("abc"), describe("  "), describe(List.of(1, 2))), List.of("int 42", "string of length 3", "blank string", "list of 2 items")));
        test("describe null and other types", () -> eq(List.of(describe(null), describe(2.5)), List.of("null", "other Double")));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

fund-java/03-control-flow-switch-and-pat.explanation:
An arrow switch expression with a block arm for the rule that needs a condition:

```java
return switch (tier) {
    case STANDARD -> orderCents >= 5000 ? 0 : 499;
    case EXPRESS -> {
        long fee = 1299;
        yield orderCents >= 10000 ? fee / 2 : fee;
    }
    case PICKUP -> 0;
};
```

No `default`: listing all three constants makes the compiler check exhaustiveness. In `describe`, test null first, then `if (value instanceof String s)` gives you `s` without a cast.

